class DataLake:
    def __init__(self):
        self.files = {}

    def write(self, path, content):
        self.files[path] = content

    def rename_dir(self, old_prefix, new_prefix):
        renamed = 0
        for path in list(self.files):
            if path.startswith(old_prefix):
                new_path = new_prefix + path[len(old_prefix):]
                self.files[new_path] = self.files.pop(path)
                renamed += 1
        return renamed

lake = DataLake()
lake.write("raw/2026/01/sales.csv", "id,amount\n1,100")
lake.write("raw/2026/01/returns.csv", "id,amount\n1,-20")
lake.write("raw/2026/02/sales.csv", "id,amount\n2,300")

moved = lake.rename_dir("raw/2026/01/", "curated/2026/01/")
print("archivos movidos:", moved)
print(sorted(lake.files))
